    max-width: 350px;
    min-width: 0;
    height: auto;
    min-height: 36px;
    position: relative;
    display: flex;
    align-items: stretch;
    flex: 1;
}

.selectTitle {
    margin-bottom: 10px;
    display: block;
}

.selector select {
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: transparent;
    appearance: none;
    -webkit-appearance: none;
    color: #fff;
    font-size: 12px;
    margin: 0px;
    padding: 8px 16px;
    border-radius: 0;
    display: block;
    max-width: 100%;
    min-width: 175px;
    vertical-align: baseline;
    white-space: nowrap;
}

.selector select:focus,
.selector select:focus-within,
.selector select:focus-visible {
    outline: none;
    border-bottom: 1px solid;
}

.dropdown-menu {
    position: absolute;
    top: calc(100% + 6px);
    z-index: 200;
    min-width: 100%;
}

.dropdown-menu--align-left {
    left: 0;
    right: auto;
}

.dropdown-menu--align-right {
    right: 0;
    left: auto;
}

.dropdown-menu__panel {
    position: relative;
    width: max-content;
    min-width: 100%;
    max-width: min(100vw - 24px, 360px);
    max-height: min(70vh, 420px);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: linear-gradient(168deg, rgba(52, 52, 56, 0.98) 0%, rgba(32, 32, 36, 0.99) 100%);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    box-shadow:
        0 20px 48px rgba(0, 0, 0, 0.45),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dropdown-menu__content {
    margin: 0;
    padding: 4px 0;
    list-style: none;
    overflow-y: auto;
    flex: 1;
    font-size: 0.875rem;
    font-weight: 500;
    color: #e4e4e4;
    text-align: left;
}

.dropdown-menu__content li {
    padding: 10px 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    border-bottom: 1px solid transparent;
    transition:
        background 0.15s ease,
        color 0.15s ease;
}

.dropdown-menu__content li:hover,
.dropdown-menu__content li:focus-visible {
    background: rgba(192, 159, 83, 0.14);
    color: #fff;
    outline: none;
}

.dropdown-menu__content li[hidden] {
    display: none !important;
}

.dropdown-menu__item--with-icon {
    display: flex;
    align-items: center;
}

.dropdown-menu-button {
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(0, 0, 0, 0.2);
    appearance: none;
    -webkit-appearance: none;
    color: #f0f0f0;
    margin: 0;
    padding: 8px 12px 8px 14px;
    border-radius: 10px;
    font-size: 0.8125rem;
    font-weight: 500;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
    line-height: 1.3;
    display: inline-flex;
    flex-direction: row;
    align-items: center;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
    vertical-align: baseline;
    justify-content: space-between;
    gap: 8px;
    cursor: pointer;
    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        box-shadow 0.2s ease;
}

.dropdown-menu-button:hover {
    border-color: rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.08);
}

.dropdown-menu-button:focus-visible {
    outline: 2px solid rgba(192, 159, 83, 0.55);
    outline-offset: 2px;
}

.dropdown-menu-button__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: left;
}

.dropdown-menu-button::after {
    content: "";
    width: 8px;
    height: 8px;
    flex-shrink: 0;
    margin-left: 4px;
    border-right: 2px solid rgba(255, 255, 255, 0.45);
    border-bottom: 2px solid rgba(255, 255, 255, 0.45);
    transform: rotate(45deg) translateY(-2px);
    transition: transform 0.2s ease;
}

.dropdown-menu-button[aria-expanded="true"]::after {
    transform: rotate(225deg) translateY(0);
}

.search-box {
    padding: 10px 10px 8px;
    flex-shrink: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.2);
}

.search-input {
    width: 100%;
    padding: 8px 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.25);
    color: #f0f0f0;
    font-size: 0.8125rem;
    font-family: inherit;
    box-sizing: border-box;
}

.search-input::placeholder {
    color: rgba(255, 255, 255, 0.35);
}

.search-input:focus {
    outline: none;
    border-color: rgba(192, 159, 83, 0.45);
    box-shadow: 0 0 0 2px rgba(192, 159, 83, 0.15);
}

.company-logo {
    margin-right: 0;
    width: 28px;
    height: 28px;
    flex-shrink: 0;
    display: block;
    object-fit: contain;
    border-radius: 6px;
}

@media screen and (min-width: 320px) and (max-width: 900px) {
    .company_container .selector {
        max-width: none;
        width: 100%;
    }

    .dropdown-menu {
        left: 0 !important;
        right: 0 !important;
        min-width: 0;
        width: 100%;
    }

    .dropdown-menu__panel {
        width: 100%;
        max-width: none;
    }

    .dropdown-menu-button {
        min-width: 0;
    }
}
